pkg = DataPackage('data/package')
ids=['sup:70110','sup:70510','sup:70530','sup:70620','sup:70210','sup:70240','sup:70250','sup:70610','sup:70710','sup:70410','sup:70140','sup:70740']
for s in ids:
    print('########', s)
    for r in pkg.query('SELECT id,part_id,quote_date,unit_price,payment_days,lead_time_days,incoterm,validity_days,remarks FROM quotes WHERE supplier_id=?', [s]):
        print('Q', r)
    for r in pkg.query('SELECT * FROM contracts WHERE supplier_id=?', [s]):
        print('C', {k:r[k] for k in r if k!='file'})
        for c in pkg.query('SELECT clause,type,text,series,material_share,deadband_pct,days FROM contract_clauses WHERE contract_id=?', [r['id']]): print('   CL', c)
    for r in pkg.query('SELECT date,topic,headline,body,source FROM news WHERE supplier_id=?', [s]): print('N', r)
